import React, { useState, useEffect } from 'react';
import { Link, NavLink, useNavigate, useLocation } from 'react-router-dom';

const Header = ({ categories, currentFilter, onFilterChange }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  
  const [darkMode, setDarkMode] = useState(() => {
    const savedMode = localStorage.getItem('darkMode');
    return savedMode === 'true';
  });

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', darkMode);
  }, [darkMode]);

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
    document.body.style.overflow = !menuOpen ? 'hidden' : '';
  };

  const closeMenu = () => {
    setMenuOpen(false);
    document.body.style.overflow = '';
  };

  const handleWorkClick = (e) => {
    e.preventDefault();
    closeMenu();
    
    if (location.pathname === '/') {
      window.scrollTo({
        top: window.innerHeight,
        behavior: 'smooth'
      });
    } else {
      navigate('/');
      setTimeout(() => {
        window.scrollTo({
          top: window.innerHeight,
          behavior: 'smooth'
        });
      }, 300);
    }
  };

  const isActive = (path) => {
    if (path === '/') return location.pathname === '/';
    return location.pathname.includes(path);
  };

  return (
    <>
      <header 
        className={`
          fixed top-0 left-0 right-0 z-50
          h-[72px] flex items-center
          transition-all duration-300
          ${scrolled 
            ? 'bg-white/90 dark:bg-black/90 backdrop-blur-md' 
            : 'bg-transparent'
          }
        `}
      >
        <div className="w-full flex items-center justify-between px-6 lg:px-12">
          <NavLink 
            to="/" 
            className="text-sm font-normal tracking-wide text-black dark:text-white hover:opacity-60 transition-opacity clickable"
            data-cursor="pointer"
          >
            SHAREEF JASIM
          </NavLink>

          <nav className="hidden lg:flex items-center gap-8">
            <a 
              href="#work" 
              onClick={handleWorkClick}
              className={`
                text-sm font-normal tracking-wide transition-opacity clickable
                ${isActive('/') && location.pathname === '/' 
                  ? 'text-black dark:text-white' 
                  : 'text-gray-500 dark:text-gray-400 hover:text-black dark:hover:text-white'
                }
              `}
              data-cursor="pointer"
            >
              Work
            </a>
            <NavLink 
              to="/About"
              className={`
                text-sm font-normal tracking-wide transition-opacity clickable
                ${isActive('/About') 
                  ? 'text-black dark:text-white' 
                  : 'text-gray-500 dark:text-gray-400 hover:text-black dark:hover:text-white'
                }
              `}
              data-cursor="pointer"
            >
              About
            </NavLink>
          </nav>

          <button 
            onClick={toggleMenu}
            className="lg:hidden flex flex-col justify-center items-center w-6 h-6 clickable"
            data-cursor="pointer"
            aria-label="Toggle menu"
          >
            <span 
              className={`
                block w-5 h-[1.5px] bg-black dark:bg-white transition-all duration-300
                ${menuOpen ? 'rotate-45 translate-y-[3px]' : ''}
              `}
            />
            <span 
              className={`
                block w-5 h-[1.5px] bg-black dark:bg-white mt-[5px] transition-all duration-300
                ${menuOpen ? '-rotate-45 -translate-y-[3px]' : ''}
              `}
            />
          </button>
        </div>
      </header>

      <div 
        className={`
          fixed inset-0 z-40 lg:hidden
          bg-white dark:bg-black
          flex flex-col items-center justify-center
          transition-all duration-500 ease-out
          ${menuOpen 
            ? 'opacity-100 pointer-events-auto' 
            : 'opacity-0 pointer-events-none'
          }
        `}
      >
        <nav className="flex flex-col items-center gap-8">
          <a 
            href="#work"
            onClick={handleWorkClick}
            className="text-2xl font-light text-black dark:text-white tracking-wide clickable"
            data-cursor="pointer"
          >
            Work
          </a>
          <Link 
            to="/About" 
            onClick={closeMenu}
            className="text-2xl font-light text-black dark:text-white tracking-wide clickable"
            data-cursor="pointer"
          >
            About
          </Link>
          
          <div className="mt-8 pt-8 border-t border-gray-200 dark:border-gray-800 flex flex-col items-center gap-4">
            <span className="text-xs uppercase tracking-wider text-gray-400 mb-2">Filter</span>
            {categories && categories.map(category => (
              <button
                key={category}
                onClick={() => { onFilterChange(category); closeMenu(); }}
                className={`
                  text-lg font-light tracking-wide transition-opacity clickable
                  ${category === currentFilter 
                    ? 'text-black dark:text-white' 
                    : 'text-gray-400 hover:text-black dark:hover:text-white'
                  }
                `}
                data-cursor="pointer"
              >
                {category}
              </button>
            ))}
          </div>
        </nav>
      </div>
    </>
  );
};

export default Header;
