// /src/components/common/CustomCursor.js
import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { gsap } from 'gsap';

const CustomCursor = () => {
  const [isMobile, setIsMobile] = useState(false);
  const cursorRef = useRef(null);
  const location = useLocation();
  const prevLocation = useRef(location.pathname);
  const isHovering = useRef(false);

  // ---- Helpers -------------------------------------------------------------

  // Force-hide default cursor everywhere (framework overrides included)
  const hideDefaultCursor = () => {
    if (isMobile) return;

    const style = document.createElement('style');
    style.id = 'custom-cursor-global-hide';
    style.textContent = `
      html, html *, body, body *,
      div, span, p, a, button, input, textarea, select, img, video,
      [role="button"], [tabindex], [onclick], [onmousedown], [onmouseup],
      .cursor-pointer, .clickable, .project-link, .about-link, .category-button,
      .nav-item, .menu-item, .header-link {
        cursor: none !important;
      }
      html:hover, body:hover, *:hover, *:active, *:focus {
        cursor: none !important;
      }
      .cursor-auto, .cursor-default, .cursor-pointer, .cursor-wait, .cursor-text,
      .cursor-move, .cursor-help, .cursor-not-allowed {
        cursor: none !important;
      }
    `;
    const existing = document.getElementById('custom-cursor-global-hide');
    if (existing) existing.remove();
    document.head.appendChild(style);

    document.documentElement.style.setProperty('cursor', 'none', 'important');
    document.body.style.setProperty('cursor', 'none', 'important');
  };

  // Keep inline cursor:none on currently hovered element
  const ensureInlineCursorNone = (x, y) => {
    if (document.documentElement.style.cursor !== 'none') {
      document.documentElement.style.setProperty('cursor', 'none', 'important');
    }
    if (document.body.style.cursor !== 'none') {
      document.body.style.setProperty('cursor', 'none', 'important');
    }
    const hovered = document.elementFromPoint(x ?? 0, y ?? 0);
    if (hovered && hovered.style && hovered.style.cursor !== 'none') {
      hovered.style.setProperty('cursor', 'none', 'important');
      hovered.style.setProperty('-webkit-cursor', 'none', 'important');
    }
  };

  // Move the custom cursor (unified for mouse & pointer events)
  const updateCursorPosition = (x, y) => {
    ensureInlineCursorNone(x, y);

    // Freeze in center under loader
    if (document.body.getAttribute('data-loading') === 'true') {
      if (cursorRef.current) {
        cursorRef.current.style.left = (window.innerWidth / 2 - 12) + 'px';
        cursorRef.current.style.top = (window.innerHeight / 2 - 12) + 'px';
      }
      return;
    }

    if (!cursorRef.current) return;
    
    // Use left/top directly instead of transform for more reliable positioning
    gsap.to(cursorRef.current, {
      left: x - 12,
      top: y - 12,
      duration: 0.15,
      ease: 'power2.out',
      overwrite: 'auto',
    });
  };

  // -------------------------------------------------------------------------

  // Apply hover/click behavior to clickable elements
  const handleHover = () => {
    if (isHovering.current || document.body.getAttribute('data-loading') === 'true') return;
    if (!cursorRef.current) return;
    isHovering.current = true;

    gsap.killTweensOf(cursorRef.current);
    cursorRef.current.classList.add('backdrop-blur-[2px]', 'will-change-[transform,backdrop-filter]');
    gsap.to(cursorRef.current, {
      scale: 1.6,
      opacity: 1,
      backgroundColor: 'rgba(132, 132, 132, 0.68)',
      duration: 0.25,
      ease: 'cubic-bezier(0.4,0,0.2,1)',
      force3D: false,
    });
  };

  const handleLeave = () => {
    if (document.body.getAttribute('data-loading') === 'true') return;
    if (!cursorRef.current) return;
    isHovering.current = false;

    gsap.killTweensOf(cursorRef.current);
    gsap.to(cursorRef.current, {
      scale: 1,
      opacity: 1,
      backgroundColor: 'rgb(0, 0, 0)',
      duration: 0.25,
      ease: 'cubic-bezier(0.4,0,0.2,1)',
      force3D: false,
      onComplete: () => {
        cursorRef.current?.classList.remove('backdrop-blur-[3px]', 'will-change-[transform,backdrop-filter]');
        cursorRef.current?.classList.add('will-change-[transform]');
      },
    });
  };

  const handleClick = () => {
    if (!cursorRef.current) return;
    gsap.killTweensOf(cursorRef.current);
    gsap.to(cursorRef.current, {
      scale: 1,
      opacity: 1,
      duration: 0.3,
      ease: 'cubic-bezier(0.4,0,0.2,1)',
      force3D: false,
    });
    isHovering.current = false;
  };

  const applyCustomCursorBehavior = () => {
    if (isMobile) return;

    const selectors = `
      a, button, [role="button"],
      input[type="submit"], input[type="button"],
      .clickable, [data-cursor="pointer"],
      .project-link, .about-link,
      .category-button,
      .nav-item, .menu-item,
      .header-link,
      [tabindex="0"]
    `;

    document.querySelectorAll(selectors).forEach((el) => {
      el.removeEventListener('mouseover', handleHover);
      el.removeEventListener('mouseout', handleLeave);
      el.removeEventListener('click', handleClick);
    });

    document.querySelectorAll(selectors).forEach((el) => {
      if (el.classList.contains('cursor-default')) return;
      el.addEventListener('mouseover', handleHover);
      el.addEventListener('mouseout', handleLeave);
      el.addEventListener('click', handleClick);
      el.style.cursor = 'none';
      el.style.transition = null;
    });
  };

  // ---- Movement listeners (the actual fix) --------------------------------

  // Fallback mousemove
  const onMouseMove = (e) => updateCursorPosition(e.clientX, e.clientY);

  // Pointer events keep firing even when an element has setPointerCapture,
  // but they go to the captured target first. By registering on window with
  // capture:true we still observe them globally.
  const onPointerMoveGlobal = (e) => updateCursorPosition(e.clientX, e.clientY);
  const onPointerDownGlobal = (e) => updateCursorPosition(e.clientX, e.clientY);

  // ---- Mount / Init --------------------------------------------------------

  // Center the cursor on mount (sits under loader)
  useEffect(() => {
    if (!cursorRef.current) return;
    const centerCursor = () => {
      cursorRef.current.style.left = (window.innerWidth / 2 - 12) + 'px';
      cursorRef.current.style.top = (window.innerHeight / 2 - 12) + 'px';
    };
    centerCursor();
    window.addEventListener('resize', centerCursor);
    return () => window.removeEventListener('resize', centerCursor);
  }, []);

  // Initialize cursor system
  useEffect(() => {
    const ua = typeof window.navigator === 'undefined' ? '' : navigator.userAgent;
    const mobile = /Android|BlackBerry|iPhone|iPad|iPod|Opera Mini|IEMobile|WPDesktop/i.test(ua);
    setIsMobile(mobile);

    if (!mobile) {
      const cursorWatchdog = setInterval(() => {
        const htmlStyle = getComputedStyle(document.documentElement);
        const bodyStyle = getComputedStyle(document.body);
        if (htmlStyle.cursor !== 'none') {
          document.documentElement.style.setProperty('cursor', 'none', 'important');
        }
        if (bodyStyle.cursor !== 'none') {
          document.body.style.setProperty('cursor', 'none', 'important');
        }

        // also enforce on the element under the last known pointer (use center as fallback)
        const cx = window.innerWidth / 2;
        const cy = window.innerHeight / 2;
        const hovered = document.elementFromPoint(cx, cy);
        if (hovered) {
          const elStyle = getComputedStyle(hovered);
          if (elStyle.cursor !== 'none') {
            hovered.style.setProperty('cursor', 'none', 'important');
            hovered.style.setProperty('-webkit-cursor', 'none', 'important');
          }
        }
      }, 100);

      document.body.classList.add('has-custom-cursor');

      // 1) Hide system cursor
      hideDefaultCursor();

      // 2) Re-hide on any mouse entry
      const handleMouseEnter = () => hideDefaultCursor();
      document.addEventListener('mouseenter', handleMouseEnter, true);
      document.addEventListener('mouseover', handleMouseEnter, true);

      // 3) Chrome-specific aggressive suppression
      const chromeCursorSuppress = (e) => {
        const t = e.target;
        if (t && t.style) {
          t.style.setProperty('cursor', 'none', 'important');
          t.style.setProperty('-webkit-cursor', 'none', 'important');
        }
        document.documentElement.style.setProperty('cursor', 'none', 'important');
        document.body.style.setProperty('cursor', 'none', 'important');
      };
      document.addEventListener('pointerover', chromeCursorSuppress, true);
      document.addEventListener('pointerdown', chromeCursorSuppress, true);
      document.addEventListener('pointerenter', chromeCursorSuppress, true);
      document.addEventListener('focus', chromeCursorSuppress, true);
      document.addEventListener('blur', chromeCursorSuppress, true);

      // 4) Movement listeners (CRITICAL)
      window.addEventListener('mousemove', onMouseMove, { passive: true });
      window.addEventListener('pointermove', onPointerMoveGlobal, { passive: true, capture: true });
      window.addEventListener('pointerdown', onPointerDownGlobal, { passive: true, capture: true });

      // 5) Apply behavior to clickable elements
      applyCustomCursorBehavior();

      // 6) Observe DOM changes and keep behavior/cursor hiding fresh
      const observer = new MutationObserver((mutations) => {
        applyCustomCursorBehavior();
        hideDefaultCursor();

        mutations.forEach((mutation) => {
          if (mutation.type === 'childList') {
            mutation.addedNodes.forEach((node) => {
              if (node.nodeType === 1) {
                node.style?.setProperty('cursor', 'none', 'important');
                if (node.querySelectorAll) {
                  node.querySelectorAll('*').forEach((child) => {
                    child.style?.setProperty('cursor', 'none', 'important');
                  });
                }
              }
            });
          }
          if (mutation.type === 'attributes' && mutation.attributeName === 'style') {
            const target = mutation.target;
            if (target.style?.cursor && target.style.cursor !== 'none') {
              target.style.setProperty('cursor', 'none', 'important');
            }
          }
        });
      });
      observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['style', 'class'],
      });

      // Cleanup
      return () => {
        clearInterval(cursorWatchdog);
        window.removeEventListener('mousemove', onMouseMove);
        window.removeEventListener('pointermove', onPointerMoveGlobal, true);
        window.removeEventListener('pointerdown', onPointerDownGlobal, true);

        document.removeEventListener('mouseenter', handleMouseEnter, true);
        document.removeEventListener('mouseover', handleMouseEnter, true);
        document.removeEventListener('pointerover', chromeCursorSuppress, true);
        document.removeEventListener('pointerdown', chromeCursorSuppress, true);
        document.removeEventListener('pointerenter', chromeCursorSuppress, true);
        document.removeEventListener('focus', chromeCursorSuppress, true);
        document.removeEventListener('blur', chromeCursorSuppress, true);

        document.body.classList.remove('has-custom-cursor');
        observer.disconnect();

        const existingStyle = document.getElementById('custom-cursor-global-hide');
        if (existingStyle) existingStyle.remove();
      };
    }
  }, [isMobile]);

  // Reset cursor visuals on route change
  useEffect(() => {
    if (location.pathname !== prevLocation.current) {
      prevLocation.current = location.pathname;
      isHovering.current = false;
      if (cursorRef.current) {
        gsap.killTweensOf(cursorRef.current);
        gsap.to(cursorRef.current, { scale: 1, opacity: 1, duration: 0.3 });
      }
      setTimeout(applyCustomCursorBehavior, 300);
    }
  }, [location]);

  if (isMobile) return null;

  return (
    <div
      ref={cursorRef}
      className="fixed rounded-none pointer-events-none"
      style={{
        width: '24px',
        height: '24px',
        left: '50%',
        top: '50%',
        zIndex: 99999,
        backgroundColor: 'rgb(0, 0, 0)',
        opacity: 1,
      }}
    />
  );
};

export default CustomCursor;
