// src/components/AnimatedSquares.js
import React, { useState, useEffect, useRef, useCallback, Fragment } from 'react';
import { gsap } from 'gsap';

const AnimatedSquares = ({
  topMargin = 1,
  bottomMargin = 1,
  leftMargin = 1,
  rightMargin = 1,
  driftX = 15,
  driftY = 15,
  count = 10,
  minSize = 20,
  maxSize = 50,
  minDuration = 0.1,
  maxDuration = 2,
  centerBias = 0.1,
}) => {
  const getSquareColors = () => {
    if (typeof window !== 'undefined') {
      const root = getComputedStyle(document.documentElement);
      const colors = [];
      for (let i = 1; i <= 14; i++) {
        const c = root.getPropertyValue(`--color-square-${i}`).trim();
        if (c) colors.push(c);
      }
      if (colors.length > 0) return colors;
    }
    return [
      '#0A0A0A', '#2D2D2D', '#525252', '#6B7280', '#8B9DAF',
      '#A3A3A3', '#B0BEC5', '#7A9E9F', '#5F8A8B', '#6B9B9E',
      '#8CB4B4', '#D4D4D4'
    ];
  };

  const containerRef = useRef(null);
  const squareRefs = useRef({});       // DOM refs for each square
  const squareDataRef = useRef([]);    // Store square data for mouse handler
  const mousePos = useRef({ x: -9999, y: -9999 }); // Track mouse in container coords
  const rafId = useRef(null);
  const [containerWidth, setContainerWidth] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);
  const [squares, setSquares] = useState([]);

  // Cursor interaction settings
  const INFLUENCE_RADIUS = 150;  // px - how close cursor must be to affect a square
  const PUSH_STRENGTH = 20;     // px - max displacement away from cursor
  const OPACITY_BOOST = 0.25;   // how much opacity increases when cursor is near

  // Generate squares
  useEffect(() => {
    if (!containerRef.current || containerWidth === 0 || containerHeight === 0) return;

    const colors = getSquareColors();
    const newSquares = Array.from({ length: count }, (_, i) => {
      const sizePct = minSize + Math.random() * (maxSize - minSize);
      const squareSizePx = (sizePct / 100) * containerWidth;
      const halfSizePx = squareSizePx / 2;

      const availableTopPx = containerHeight - (topMargin / 100) * containerHeight - (bottomMargin / 100) * containerHeight - squareSizePx;
      const availableLeftPx = containerWidth - (leftMargin / 100) * containerWidth - (rightMargin / 100) * containerWidth - squareSizePx;

      const topBiased = 0.5 + (Math.random() - 0.5) * centerBias;
      const leftBiased = 0.5 + (Math.random() - 0.5) * centerBias;

      const centerTopPx = (topMargin / 100) * containerHeight + halfSizePx + topBiased * availableTopPx;
      const centerLeftPx = (leftMargin / 100) * containerWidth + halfSizePx + leftBiased * availableLeftPx;

      const topPx = centerTopPx - halfSizePx;
      const leftPx = centerLeftPx - halfSizePx;

      const maxDriftXFromCenter = Math.min(
        centerLeftPx - (leftMargin / 100) * containerWidth - halfSizePx,
        (containerWidth - (rightMargin / 100) * containerWidth - halfSizePx) - centerLeftPx
      );
      const maxDriftYFromCenter = Math.min(
        centerTopPx - (topMargin / 100) * containerHeight - halfSizePx,
        (containerHeight - (bottomMargin / 100) * containerHeight - halfSizePx) - centerTopPx
      );

      const actualDriftX = Math.min((driftX / 100) * containerWidth, maxDriftXFromCenter);
      const actualDriftY = Math.min((driftY / 100) * containerHeight, maxDriftYFromCenter);

      const driftXPx = (Math.random() * 2 - 1) * actualDriftX;
      const driftYPx = (Math.random() * 2 - 1) * actualDriftY;

      const delay = Math.random() * maxDuration;
      const duration = Math.random() * (maxDuration - minDuration) + minDuration;
      const zIndex = i + 5;
      const color = colors[Math.floor(Math.random() * colors.length)];

      return {
        id: i, topPx, leftPx, squareSizePx, driftXPx, driftYPx,
        delay, duration, zIndex, color,
        centerTopPx, centerLeftPx, actualDriftX, actualDriftY
      };
    });

    setSquares(newSquares);
    squareDataRef.current = newSquares;
  }, [count, minSize, maxSize, topMargin, bottomMargin, leftMargin, rightMargin, driftX, driftY, minDuration, maxDuration, centerBias, containerWidth, containerHeight]);

  // Resize observer
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        setContainerWidth(containerRef.current.offsetWidth);
        setContainerHeight(containerRef.current.offsetHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Ambient float animation (no rotation — straight angles only)
  useEffect(() => {
    if (!containerRef.current || squares.length === 0) return;

    gsap.killTweensOf(containerRef.current.querySelectorAll('[data-square-id]'));

    squares.forEach((square) => {
      const el = squareRefs.current[square.id];
      if (!el) return;

      const tl = gsap.timeline({
        repeat: -1,
        yoyo: true,
        delay: square.delay
      });

      tl.to(el, {
        x: square.driftXPx,
        y: square.driftYPx,
        duration: square.duration,
        ease: "sine.inOut",
        force3D: false
      })
      .to(el, {
        x: -square.driftXPx * 0.5,
        y: -square.driftYPx * 0.5,
        duration: square.duration * 1.1,
        ease: "sine.inOut",
        force3D: false
      });
    });
  }, [squares]);

  // Cursor interaction — gentle repulsion + opacity shift
  const updateCursorEffect = useCallback(() => {
    const mx = mousePos.current.x;
    const my = mousePos.current.y;
    const data = squareDataRef.current;

    data.forEach((sq) => {
      const el = squareRefs.current[sq.id];
      if (!el) return;

      // Get current center of the square (original position + half size)
      const cx = sq.leftPx + sq.squareSizePx / 2;
      const cy = sq.topPx + sq.squareSizePx / 2;

      const dx = cx - mx;
      const dy = cy - my;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < INFLUENCE_RADIUS && mx > -999) {
        // Normalize: 1 at cursor, 0 at edge of influence
        const strength = 1 - dist / INFLUENCE_RADIUS;
        // Ease the strength for a softer falloff (quadratic)
        const eased = strength * strength;

        // Push direction (away from cursor)
        const angle = Math.atan2(dy, dx);
        const pushX = Math.cos(angle) * PUSH_STRENGTH * eased;
        const pushY = Math.sin(angle) * PUSH_STRENGTH * eased;

        // Boost opacity when cursor is close
        const targetOpacity = 0.6 + OPACITY_BOOST * eased;

        gsap.to(el, {
          '--pushX': pushX,
          '--pushY': pushY,
          opacity: targetOpacity,
          duration: 0.4,
          ease: "power2.out",
          overwrite: 'auto',
          force3D: false,
          onUpdate() {
            const px = parseFloat(gsap.getProperty(el, '--pushX')) || 0;
            const py = parseFloat(gsap.getProperty(el, '--pushY')) || 0;
            el.style.marginLeft = `${px}px`;
            el.style.marginTop = `${py}px`;
          }
        });
      } else {
        // Return to rest
        gsap.to(el, {
          '--pushX': 0,
          '--pushY': 0,
          opacity: 0.6,
          duration: 0.8,
          ease: "power2.out",
          overwrite: 'auto',
          force3D: false,
          onUpdate() {
            const px = parseFloat(gsap.getProperty(el, '--pushX')) || 0;
            const py = parseFloat(gsap.getProperty(el, '--pushY')) || 0;
            el.style.marginLeft = `${px}px`;
            el.style.marginTop = `${py}px`;
          }
        });
      }
    });
  }, []);

  // Mouse tracking on the container
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const onMouseMove = (e) => {
      const rect = container.getBoundingClientRect();
      mousePos.current.x = e.clientX - rect.left;
      mousePos.current.y = e.clientY - rect.top;

      // Throttle updates to ~60fps via rAF
      if (!rafId.current) {
        rafId.current = requestAnimationFrame(() => {
          updateCursorEffect();
          rafId.current = null;
        });
      }
    };

    const onMouseLeave = () => {
      mousePos.current.x = -9999;
      mousePos.current.y = -9999;
      updateCursorEffect(); // Reset all squares
    };

    container.addEventListener('mousemove', onMouseMove, { passive: true });
    container.addEventListener('mouseleave', onMouseLeave);

    return () => {
      container.removeEventListener('mousemove', onMouseMove);
      container.removeEventListener('mouseleave', onMouseLeave);
      if (rafId.current) cancelAnimationFrame(rafId.current);
    };
  }, [updateCursorEffect]);

  return (
    <div ref={containerRef} className="absolute inset-0 isolate">
      {squares.map((square) => {
        const { id, topPx, leftPx, squareSizePx, zIndex, color } = square;

        return (
          <Fragment key={id}>
            <div
              data-square-id={id}
              ref={(el) => { squareRefs.current[id] = el; }}
              className="absolute backdrop-blur-sm pointer-events-none"
              style={{
                width: `${squareSizePx}px`,
                height: `${squareSizePx}px`,
                top: `${topPx}px`,
                left: `${leftPx}px`,
                zIndex,
                backgroundColor: `${color}40`,
                opacity: 0.6,
                willChange: 'transform, opacity, margin',
                transition: 'background-color 0.3s ease',
              }}
            />
          </Fragment>
        );
      })}
    </div>
  );
};

export default AnimatedSquares;
