// /src/components/CategoryFilter.js
import React, { useState, useEffect } from "react";

function CategoryFilter({ categories, activeCategory, onSelectCategory }) {
  const [showFilter, setShowFilter] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setShowFilter(window.scrollY >= (window.innerHeight * 0.6));
    };
    window.addEventListener("scroll", handleScroll);
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <div
      className={`
        sticky top-0 z-50
        w-full h-[72px]
        pointer-events-none
        transition-all duration-500 ease-out
        ${showFilter 
          ? 'opacity-100' 
          : 'opacity-0'
        }
      `}
    >
      <div className="flex flex-wrap items-center justify-center gap-x-6 lg:gap-x-8 h-full px-6 lg:px-12 pointer-events-auto">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => onSelectCategory(cat)}
            className={`
              relative text-sm font-light tracking-wide
              py-1 transition-all duration-300
              clickable
              ${cat === activeCategory 
                ? 'text-black dark:text-white' 
                : 'text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300'
              }
            `}
            data-cursor="pointer"
          >
            {cat}
            <span 
              className={`
                absolute bottom-0 left-0 right-0 h-[1px]
                bg-black dark:bg-white
                transition-transform duration-300 origin-left
                ${cat === activeCategory ? 'scale-x-100' : 'scale-x-0'}
              `}
            />
          </button>
        ))}
      </div>
    </div>
  );
}

export default CategoryFilter;
