import React, { useState, useEffect, useRef, useCallback } from 'react';
import './ImageSlider.css';

const ImageSlider = ({
  images = [],
  autoPlay = true,
  autoPlayInterval = 1000,
  fadeTransitionDuration = 300,
  sliderHeight = 4,
  sliderThumbSize = 6,
  sliderMargin = 20,
  showSlider = true,
  showFrameCounter = true,
  onFrameChange = null,
  className = '',
  imageStyle = {},
  containerStyle = {}
}) => {
  const [currentFrame, setCurrentFrame] = useState(0);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [isDragging, setIsDragging] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const sliderRef = useRef(null);
  const intervalRef = useRef(null);
  const imageContainerRef = useRef(null);

  // Auto-play functionality
  useEffect(() => {
    if (isPlaying && !isDragging && !isHovering && images.length > 1) {
      intervalRef.current = setInterval(() => {
        setCurrentFrame(prev => (prev + 1) % images.length);
      }, autoPlayInterval);
    } else {
      clearInterval(intervalRef.current);
    }

    return () => clearInterval(intervalRef.current);
  }, [isPlaying, isDragging, isHovering, images.length, autoPlayInterval]);

  // Handle frame change callback
  useEffect(() => {
    if (onFrameChange && typeof onFrameChange === 'function') {
      onFrameChange(currentFrame, images[currentFrame]);
    }
  }, [currentFrame, onFrameChange, images]);

  // Calculate slider position based on current frame
  const getSliderPosition = useCallback(() => {
    if (images.length <= 1) return 0;
    return (currentFrame / (images.length - 1)) * 100;
  }, [currentFrame, images.length]);

  // Handle slider click/drag
  const handleSliderInteraction = useCallback((event) => {
    if (!sliderRef.current || images.length <= 1) return;

    const rect = sliderRef.current.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const percentage = Math.max(0, Math.min(100, (x / rect.width) * 100));
    const frameIndex = Math.round((percentage / 100) * (images.length - 1));
    
    setCurrentFrame(frameIndex);
  }, [images.length]);

  // Mouse down handler for slider
  const handleMouseDown = useCallback((event) => {
    event.preventDefault();
    setIsDragging(true);
    setIsPlaying(false);
    handleSliderInteraction(event);

    const handleMouseMove = (e) => {
      handleSliderInteraction(e);
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  }, [handleSliderInteraction]);

  // Handle slider hover
  const handleSliderMouseEnter = () => {
    setIsHovering(true);
    setIsPlaying(false);
  };

  const handleSliderMouseLeave = () => {
    setIsHovering(false);
    if (autoPlay && !isDragging) {
      setIsPlaying(true);
    }
  };

  // Handle container hover to pause auto-play
  const handleContainerMouseEnter = () => {
    if (autoPlay) {
      setIsPlaying(false);
    }
  };

  const handleContainerMouseLeave = () => {
    if (autoPlay && !isDragging && !isHovering) {
      setIsPlaying(true);
    }
  };

  if (!images || images.length === 0) {
    return (
      <div className={`image-slider-container ${className}`} style={containerStyle}>
        <div className="image-slider-placeholder">No images provided</div>
      </div>
    );
  }

  return (
    <div 
      className={`image-slider-container ${className}`}
      style={containerStyle}
      onMouseEnter={handleContainerMouseEnter}
      onMouseLeave={handleContainerMouseLeave}
    >
      {/* Image Display Area */}
      <div 
        className="image-slider-display"
        ref={imageContainerRef}
        style={{ position: 'relative', overflow: 'hidden' }}
      >
        {images.map((image, index) => (
          <img
            key={index}
            src={image}
            alt={`Frame ${index + 1}`}
            className={`image-slider-frame ${index === currentFrame ? 'active' : ''}`}
            style={{
              ...imageStyle,
              position: index === 0 ? 'relative' : 'absolute',
              top: index === 0 ? 'auto' : 0,
              left: index === 0 ? 'auto' : 0,
              width: '100%',
              height: 'auto',
              opacity: index === currentFrame ? 1 : 0,
              transition: `opacity ${fadeTransitionDuration}ms ease-in-out`,
              display: 'block'
            }}
            draggable={false}
          />
        ))}
      </div>

      {/* Custom Slider */}
      {showSlider && images.length > 1 && (
        <div 
          className="image-slider-controls"
          style={{ marginTop: `${sliderMargin}px` }}
        >
          <div
            ref={sliderRef}
            className="image-slider-track"
            style={{ 
              height: `${sliderHeight}px`,
              position: 'relative',
              cursor: 'none',
              userSelect: 'none'
            }}
            data-cursor="pointer"
            onMouseDown={handleMouseDown}
            onMouseEnter={handleSliderMouseEnter}
            onMouseLeave={handleSliderMouseLeave}
          >
            {/* Progress Track */}
            <div className="slider-track-bg" />
            <div 
              className="slider-track-progress"
              style={{ 
                width: `${getSliderPosition()}%`
              }}
            />
            
            {/* Slider Thumb */}
            <div
              className="slider-thumb"
              style={{
                left: `${getSliderPosition()}%`,
                width: `${sliderThumbSize}px`,
                height: `${sliderThumbSize}px`,
                transform: 'translateX(-50%) translateY(-50%)',
                top: '50%'
              }}
              data-cursor="pointer"
            />
          </div>

          {/* Frame Counter */}
          {showFrameCounter && (
            <div className="image-slider-counter">
              {currentFrame + 1} / {images.length}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ImageSlider;
