import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { gsap } from 'gsap';
import { ReactComponent as ArrowTopIcon } from '../../assets/icons/arrow-up-340-svgrepo-com.svg';

const GoToTopButton = () => {
  const [isAtTop, setIsAtTop] = useState(true);
  const location = useLocation();
  const hidden = location.pathname === '/ComputationalDesign' || location.pathname === '/CompDesign2';

  useEffect(() => {
    const checkPosition = () => {
      setIsAtTop(window.scrollY < window.innerHeight * 0.5);
    };
    window.addEventListener('scroll', checkPosition);
    checkPosition();
    return () => window.removeEventListener('scroll', checkPosition);
  }, []);

  const handleClick = () => {
    const target = isAtTop ? window.innerHeight : 0;
    const duration = isAtTop ? 1.2 : 0.8;
    
    gsap.to({ y: window.scrollY }, {
      y: target,
      duration: duration,
      ease: "power2.inOut",
      onUpdate: function() {
        window.scrollTo(0, this.targets()[0].y);
      }
    });
  };

  return hidden ? null : (
    <button
      onClick={handleClick}
      className="
        fixed z-50 
        bg-black dark:bg-white 
        hover:opacity-70 
        transition-opacity duration-200
        clickable
      "
      style={{
        left: 'calc(50% - 12px)',
        bottom: '24px',
        width: '24px',
        height: '24px',
        padding: '2px'
      }}
      aria-label={isAtTop ? "Scroll to work" : "Scroll to top"}
      data-cursor="pointer"
    >
      <div
        style={{
          transform: isAtTop ? 'scaleY(-1)' : 'scaleY(1)',
          transition: 'transform 0.3s ease-in-out',
        }}
        className="w-full h-full"
      >
        <ArrowTopIcon className="w-full h-full invert dark:invert-0" />
      </div>
    </button>
  );
};

export default GoToTopButton;
