// /src/pages/HomePage.js
import React, { useState, useEffect } from "react";
import AnimatedSquares from '../components/common/AnimatedSquares.js';
import CategoryFilter from "../components/common/CategoryFilter";
import ProjectBoard from "../components/common/ProjectBoard";
import projectsData from "../components/projects/projectsData";
import { useNavigationType, useLocation } from 'react-router-dom';
import { useLayoutEffect } from 'react';

const uniqueCategories = Array.from(
  new Set(projectsData.flatMap((project) => project.categories))
);
const categoriesList = ["All Projects", ...uniqueCategories];

function HomePage() {
  const [activeCategory, setActiveCategory] = useState(() => {
    return localStorage.getItem('homePageFilter') || "All Projects";
  });

  useEffect(() => {
    localStorage.setItem('homePageFilter', activeCategory);
  }, [activeCategory]);

  useEffect(() => {
    const save = () => {
      sessionStorage.setItem('homePageScrollPosition', String(window.scrollY));
    };
    window.addEventListener('beforeunload', save);
    return () => {
      save();
      window.removeEventListener('beforeunload', save);
    };
  }, []);

  const navType = useNavigationType();
  const location = useLocation();
  useLayoutEffect(() => {
    if (navType !== 'POP') {
      window.scrollTo(0, 0);
      sessionStorage.removeItem('homePageScrollPosition');
      return;
    }
    const saved = sessionStorage.getItem('homePageScrollPosition');
    if (saved) {
      window.scrollTo(0, parseInt(saved, 10));
    }
  }, [navType, location.key]);

  const filteredProjects =
    activeCategory === "All Projects"
      ? projectsData
      : projectsData.filter((proj) => proj.categories.includes(activeCategory));

  const handleSquareClick = (node) => {};

  const handleFilterChange = (category) => {
    setActiveCategory(category);
  };

  return (
    <div className="min-h-screen bg-white dark:bg-black transition-colors duration-500">
      
      <section className="min-h-screen flex items-center bg-white dark:bg-black">
        <div className="w-full grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-0 px-6 lg:px-12 py-24 lg:py-0">
          
          <div className="flex flex-col justify-center max-w-xl">
            <h1 className="text-display mb-6">
              Hi, I'm Shareef
            </h1>
            <p className="text-body-lg text-secondary leading-relaxed">
              An interdisciplinary designer, researcher, and technologist exploring 
              novel technologies and their applications across domains.
            </p>
          </div>

          <div className="relative w-full h-[50vh] lg:h-[70vh]">
            <AnimatedSquares
              topMargin={1}
              bottomMargin={1}
              leftMargin={1}
              rightMargin={1}
              driftX={15}
              driftY={15}
              count={17}
              minSize={6}
              maxSize={25}
              minDuration={4}
              maxDuration={18}
              centerBias={0.8}
            />
          </div>
        </div>
      </section>

      <section id="work" className="bg-white dark:bg-black">
        <CategoryFilter
          categories={categoriesList}
          activeCategory={activeCategory}
          onSelectCategory={handleFilterChange}
        />
        
        <ProjectBoard
          projects={filteredProjects}
          selectedCategory={activeCategory}
          onSquareClick={handleSquareClick}
        />
      </section>
    </div>
  );
}

export default HomePage;
