// /src/components/ProjectBoard.js
import React, { useMemo, useState, useEffect, useRef } from "react";
import ReactDOM from "react-dom";
import { motion, AnimatePresence } from "framer-motion";
import ProjectSquare from "./ProjectSquare";

function ProjectBoard({ projects, selectedCategory, onSquareClick }) {
  const gridRef = useRef(null);
  const [cols, setCols] = useState(6);
  const [cellSize, setCellSize] = useState(200);
  const [hoveredProject, setHoveredProject] = useState(null);

  useEffect(() => {
    const updateGridInfo = () => {
      if (!gridRef.current) return;
      const gridStyle = window.getComputedStyle(gridRef.current);
      const gridTemplateCols = gridStyle.getPropertyValue("grid-template-columns");
      const colArray = gridTemplateCols.split(" ").filter(Boolean);
      setCols(colArray.length || 1);
      
      const containerWidth = gridRef.current.clientWidth;
      const gapValue = window.innerWidth >= 1024 ? 32 : 24;
      const numberOfGaps = colArray.length - 1;
      const availableWidth = containerWidth - (numberOfGaps * gapValue);
      const computedCellSize = Math.floor(availableWidth / colArray.length);
      setCellSize(computedCellSize);
    };

    updateGridInfo();
    window.addEventListener("resize", updateGridInfo);
    return () => window.removeEventListener("resize", updateGridInfo);
  }, [projects, selectedCategory]);

  const sortedProjects = useMemo(() => {
    return [...projects].sort((a, b) => (a.order || 0) - (b.order || 0));
  }, [projects]);

  // Blur overlay rendered via portal so it sits above header/footer/filter
  const blurOverlay = ReactDOM.createPortal(
    <div
      className={`
        fixed inset-0 pointer-events-none
        transition-all duration-400 ease-in-out
        ${hoveredProject
          ? 'opacity-100 backdrop-blur-[6px] bg-white/20 dark:bg-black/40'
          : 'opacity-0 backdrop-blur-none bg-transparent'
        }
      `}
      style={{ zIndex: 9990 }}
    />,
    document.body
  );

  return (
    <div className="px-6 lg:px-12 py-12 lg:py-16 max-w-[1440px] mx-auto overflow-visible relative">
      {blurOverlay}

      <motion.div
        ref={gridRef}
        className="
          grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6
          gap-6 lg:gap-8
          min-h-screen
          overflow-visible
        "
        style={{
          gridAutoFlow: 'row',
          gridAutoRows: `${cellSize}px`
        }}
        layout
      >
        <AnimatePresence mode="popLayout">
          {sortedProjects.map((project) => {
            const colSpan = project.colSpan || 1;
            const rowSpan = project.rowSpan || 1;

            return (
              <motion.div
                key={project.title}
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ 
                  duration: 0.4, 
                  ease: [0.4, 0, 0.2, 1]
                }}
                style={{
                  gridColumn: `span ${Math.min(colSpan, cols)}`,
                  gridRow: `span ${rowSpan}`
                }}
              >
                <ProjectSquare
                  project={project}
                  isSelected={false}
                  onClick={onSquareClick}
                  onHoverChange={(hovered) => setHoveredProject(hovered ? project.title : null)}
                />
              </motion.div>
            );
          })}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

export default ProjectBoard;
